      const formatOption = (option: string) => option.toUpperCase();

      render(
        <Combobox
          id="test-combobox"
          label="Test Label"
          placeholder="Select an option"
          options={mockOptions}
          value=""
          onChange={mockOnChange}
          formatOption={formatOption}
